def assemble_provenance(needs_df):
    rows = []
    for _, row in needs_df.iterrows():
        rows.append({'record_id': row.get('record_id', ''), 'source_id': row.get('source_id', ''), 'source_weight': row.get('source_weight', 0), 'demand_score': row.get('demand_score', 0)})
    ordered = sorted(rows, key=lambda item: (-item.get('demand_score', 0), item.get('record_id', '')))
    evidence_records = []
    for position, item in enumerate(ordered, start=1):
        evidence_records.append({'record_id': item.get('record_id', ''), 'source_id': item.get('source_id', ''), 'source_weight': item.get('source_weight', 0), 'rank': position})
    return pd.DataFrame(evidence_records)

